        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_model.Steps" />
        <ValidationMessage For="() => _model.Steps" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private int _newRecipeId;

    private void HandleSubmit()
    {
        var recipe = Store.Add(new Recipe
        {
            Title = _model.Title,
            Category = _model.Category,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        });
        _newRecipeId = recipe.Id;
        _submitted = true;
        _model = new();
    }

    private class RecipeFormModel
    {
        [Required(ErrorMessage = "Title is required.")]
        [StringLength(100, ErrorMessage = "Title is too long.")]
        public string Title { get; set; } = "";

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = "";

        [Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = "";

        [Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = "";
    }
}
"}

toolArgs.file_text:
namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeStore
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeStore()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.",
                Ratings = [5, 4, 5, 4]
            },
            new()
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale or pancetta\nEgg yolks\nPecorino Romano\nBlack pepper",
                Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk egg yolks with grated pecorino and pepper.\n4. Toss hot pasta with guanciale, remove from heat.\n5. Stir in egg mixture quickly to create creamy sauce.",
                Ratings = [5, 5, 4]
            },
            new()
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
                Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and spices, simmer 15 min.\n5. Add cream and cooked chicken, simmer 10 min.\n6. Serve with basmati rice or naan.",
                Ratings = [5, 4, 5]
            },
            new()
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nEggs",
                Steps = "1. Soak rice noodles in warm water 20 min.\n2. Make sauce: mix tamarind, fish sauce, sugar.\n3. Stir-fry tofu until golden, set aside.\n4. Scramble eggs in wok.\n5. Add noodles and sauce, toss until coated.\n6. Add tofu, bean sprouts, and green onions.\n7. Serve with crushed peanuts and lime.",
                Ratings = [4, 4, 5]
            },
            new()
            {
                Id = 5, Title = "Guacamole", Category = "Mexican",
                Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nCumin",
                Steps = "1. Halve and pit avocados, scoop into bowl.\n2. Mash to desired consistency.\n3. Stir in lime juice, diced onion, jalapeño, tomato.\n4. Add chopped cilantro, salt, and cumin.\n5. Serve immediately with tortilla chips.",
                Ratings = [5, 5]
            },
            new()
            {
                Id = 6, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = "Ground beef\nTaco seasoning\nTortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
                Steps = "1. Brown ground beef in skillet, drain fat.\n2. Add taco seasoning and water, simmer 5 min.\n3. Warm tortillas.\n4. Fill with beef, top with lettuce, tomato, cheese.\n5. Add sour cream and salsa.",
                Ratings = [4, 5, 4]
            },
            new()
            {
                Id = 7, Title = "Green Curry", Category = "Thai",
                Ingredients = "Green curry paste\nCoconut milk\nChicken or tofu\nBamboo shoots\nThai basil\nBell pepper\nFish sauce\nSugar",
                Steps = "1. Heat curry paste in pot until fragrant.\n2. Add coconut milk, stir until combined.\n3. Add chicken/tofu, simmer until cooked.\n4. Add bamboo shoots, bell pepper.\n5. Season with fish sauce and sugar.\n6. Garnish with Thai basil, serve over rice.",
                Ratings = [5, 4]
            },
            new()
            {
                Id = 8, Title = "Palak Paneer", Category = "Indian",
                Ingredients = "Paneer\nSpinach\nOnion\nGarlic\nGinger\nGreen chili\nCumin\nGaram masala\nCream",
                Steps = "1. Blanch spinach, blend into smooth purée.\n2. Fry paneer cubes until golden, set aside.\n3. Sauté cumin, onion, garlic, ginger, chili.\n4. Add spinach purée, cook 5 min.\n5. Add paneer and cream, simmer 5 min.\n6. Serve with naan or rice.",
                Ratings = [4, 5, 5]
            },
        ];
        _nextId = 9;
    }

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
            recipe.Ratings.Add(stars);
    }

    public Recipe Add(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
        return recipe;
    }
}

@rendermode InteractiveServer
@using RecipeShare.Models
@inject RecipeStore Store

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    <span class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="star-btn @(star <= _selectedRating ? "filled" : "")"
                    @onclick="() => Rate(star)"
                    title="@star star(s)"
                    disabled="@_hasRated">
                @(star <= _selectedRating ? "★" : "☆")
            </button>
        }
    </span>
    @if (_hasRated)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
    <span class="rating-avg">
        Avg: @Store.GetById(RecipeId)?.AverageRating.ToString("0.0") ★
        (@Store.GetById(RecipeId)?.Ratings.Count ratings)
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _selectedRating;
    private bool _hasRated;

    private void Rate(int stars)
    {
        if (_hasRated) return;
        _selectedRating = stars;
        _hasRated = true;
        Store.AddRating(RecipeId, stars);
    }
}

