@page "/recipes/{CategoryName}"
@using RecipeShare.Models
@inject RecipeStore Store

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@{
    var recipes = Store.GetByCategory(CategoryName ?? "");
}

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-grid">
        @foreach (var recipe in recipes)
        {
            <div class="recipe-card">
                <h3><a href="/recipe/@recipe.Id">@recipe.Title</a></h3>
                <p class="recipe-meta">
                    @if (recipe.Ratings.Count > 0)
                    {
                        <span>★ @recipe.AverageRating.ToString("0.0")</span>
                        <span>(@recipe.Ratings.Count ratings)</span>
                    }
                    else
                    {
                        <span>No ratings yet</span>
                    }
                </p>
            </div>
        }
    </div>
}

<p><a href="/">← Back to categories</a></p>

@code {
    [Parameter] public string? CategoryName { get; set; }
}

