toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer
@using System.ComponentModel.DataAnnotations
@using RecipeShare.Models
@inject RecipeStore Store
@inject NavigationManager Nav

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@_model.Title" has been added.
        <a href="/recipe/@_newRecipeId">View it here</a>.
    </div>
}

<EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="_model.Title" />
        <ValidationMessage For="() => _model.Title" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
            <option value="">-- Select category --</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Thai">Thai</option>
            <option value="Mexican">Mexican</option>
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => _model.Category" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients" />
        <ValidationMessage For="() => _model.Ingredients" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_model.Steps" />
        <ValidationMessage For="() => _model.Steps" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private int _newRecipeId;

    private void HandleSubmit()
    {
        var recipe = Store.Add(new Recipe
        {
            Title = _model.Title,
            Category = _model.Category,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        });
        _newRecipeId = recipe.Id;
        _submitted = true;
        _model = new();
    }

    private class RecipeFormModel
    {
        [Required(ErrorMessage = "Title is required.")]
        [StringLength(100, ErrorMessage = "Title is too long.")]
        public string Title { get; set; } = "";

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = "";

        [Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = "";

        [Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = "";
    }
}

